import type{EditBlueprint,ScriptPackage}from"../../core/contracts"
import{scriptPackage}from"./editorial-positive"
export function approvedEditScript(runId="edit-fixture"):ScriptPackage{const s=scriptPackage(runId);return{...s,status:"SCRIPT_APPROVED",qc:{decision:"SCRIPT_APPROVED",findings:[],estimatedRuntimeSeconds:s.targetRuntimeSeconds},assetBudget:{...s.assetBudget,generatedVideo:4,generatedImage:4,evidenceInsert:4,motionGraphic:4,mapOrDiagram:2,atmosphericImage:2,manualReviewSlots:2}}}
export function negativeBlueprint(b:EditBlueprint):EditBlueprint{const x=structuredClone(b);x.status="DRAFT";x.sequences[0].dramaticFunction="" as never;x.shots[0].durationSec=0;x.shots[0].representationType="DRAMATIZATION";x.shots[0].labelRequired=false;x.shots[0].evidenceIds=[];x.transitionPlan[0].reason="";x.productionBudget.exceeded=["TOTAL_ASSET_BUDGET_EXCEEDED"];x.estimatedRuntimeSeconds+=100;x.dependencyGraph.edges.push({from:x.shots[0].shotId,to:x.assetRequests[0].assetRequestId,relation:"REQUIRES"});return x}
